"""Builds a TradingView Pine Script v6 indicator that draws today's levels.

TradingView cannot read this app, so the levels are pasted in as arrays. Re-paste a fresh version each session.
This code was written to be conservative Pine v6; it has not been compiled by TradingView from here.
"""
from __future__ import annotations
import re

TEMPLATE = '''//@version=6
indicator("Options levels (pasted)", overlay = true, max_lines_count = 100, max_labels_count = 100, max_boxes_count = 50)

// ---- Generated by NQ-ES Options Analytics ----
// __SOURCE__
// __UNITS__
// Each line STARTS when that level first appeared and runs to the current candle, ending in a small block with the label.
// Levels are ESTIMATES from delayed options data. They are context, not signals.

var float[]  lvPrice = array.from(__PRICES__)
var string[] lvName  = array.from(__NAMES__)
var string[] lvCat   = array.from(__CATS__)
var float[]  lvLow   = array.from(__LOWS__)       // zone bottom (0 = this level is a single line)
var float[]  lvHigh  = array.from(__HIGHS__)      // zone top
var int[]    lvStart = array.from(__STARTS__)      // when each level first appeared (UTC milliseconds); 0 = unknown

showFlip   = input.bool(true, "Gamma flip")
showGex    = input.bool(true, "GEX concentration")
showOi     = input.bool(true, "Open interest")
showVol    = input.bool(true, "Volume")
showMove   = input.bool(true, "Expected move")
showCustom = input.bool(true, "Levels you typed in")
showZones  = input.bool(true, "GEX call and put wall zones")
showNet    = input.bool(true, "Positive and negative GEX zones")
offsetPts  = input.float(0.0, "Add to every level (points)")
startMode  = input.string("Level time", "Lines start at", options = ["Level time", "Session open 9:30 ET", "Start of chart data"])
extBars    = input.int(3, "Lines run this many bars past the current candle", minval = 0)
maxDistPct = input.float(5.0, "Hide levels farther than this % from price", minval = 0.1)
showBlocks = input.bool(true, "Show the small block with the label")
bandFarPct = input.float(1.0, "Zones farther than this % from price are drawn as a line", minval = 0.0, step = 0.1)

var int levelTime = __START__

colorFor(string cat) =>
    switch cat
        "gamma_flip" => #e6b422
        "gex_concentration" => #2f8bf5
        "gex0_call_wall" => #22d3ee
        "gex0_put_wall" => #ff4d8d
        "gex0_flip" => #ffd166
        "open_interest" => #ff7a2e
        "oi_by_expiry" => #ff7a2e
        "oi_mid" => #ff7a2e
        "volume" => #3fb96a
        "volume_by_expiry" => #3fb96a
        "volume_mid" => #3fb96a
        "expected_move" => #7db7ff
        "expected_move_ext" => #8e9bff
        "custom" => #ffffff
        "gex_call_zone" => #3fb96a
        "gex_put_zone" => #e5534b
        "gex_pos_zone" => #2f8bf5
        "gex_neg_zone" => #a371f7
        "oi_call_zone" => #ff9f43
        "oi_put_zone" => #d9480f
        "volume_call_zone" => #2ec4b6
        "volume_put_zone" => #f06292
        => color.gray

visibleCat(string cat) =>
    switch cat
        "gamma_flip" => showFlip
        "gex_concentration" => showGex
        "gex0_call_wall" => showGex
        "gex0_put_wall" => showGex
        "gex0_flip" => showGex
        "open_interest" => showOi
        "oi_by_expiry" => showOi
        "oi_mid" => showOi
        "volume" => showVol
        "volume_by_expiry" => showVol
        "volume_mid" => showVol
        "expected_move" => showMove
        "expected_move_ext" => showMove
        "custom" => showCustom
        "gex_call_zone" => showZones
        "gex_put_zone" => showZones
        "gex_pos_zone" => showNet
        "gex_neg_zone" => showNet
        "oi_call_zone" => showOi
        "oi_put_zone" => showOi
        "volume_call_zone" => showVol
        "volume_put_zone" => showVol
        => true

var line[]  lns = array.new<line>()
var label[] lbs = array.new<label>()
var box[]   bxs = array.new<box>()

if barstate.islast
    for l in lns
        line.delete(l)
    for b in lbs
        label.delete(b)
    for x in bxs
        box.delete(x)
    array.clear(lns)
    array.clear(lbs)
    array.clear(bxs)
    sessionOpen = timestamp("America/New_York", year(time, "America/New_York"), month(time, "America/New_York"), dayofmonth(time, "America/New_York"), 9, 30, 0)
    firstBarTime = time[math.min(bar_index, 4999)]
    startAt = switch startMode
        "Session open 9:30 ET" => sessionOpen
        "Start of chart data" => firstBarTime
        => na(levelTime) ? sessionOpen : levelTime
    startX = math.min(startAt, time)
    endX = time + extBars * timeframe.in_seconds() * 1000
    if array.size(lvPrice) > 0
        for i = 0 to array.size(lvPrice) - 1
            cat = array.get(lvCat, i)
            p = array.get(lvPrice, i) + offsetPts
            st = array.get(lvStart, i)
            startI = startMode == "Level time" ? (st > 0 ? st : startX) : startX
            if visibleCat(cat) and math.abs(p - close) / close * 100 <= maxDistPct
                c = (cat == "oi_mid" or cat == "volume_mid") ? color.new(colorFor(cat), 45) : colorFor(cat)
                zLow = array.get(lvLow, i)
                zHigh = array.get(lvHigh, i)
                bandDistPct = close >= zLow + offsetPts and close <= zHigh + offsetPts ? 0.0 : math.min(math.abs(close - zLow - offsetPts), math.abs(close - zHigh - offsetPts)) / close * 100
                if zHigh > zLow and zLow > 0 and bandDistPct <= bandFarPct
                    array.push(bxs, box.new(math.min(startI, time), zHigh + offsetPts, endX, zLow + offsetPts, xloc = xloc.bar_time, border_color = c, border_width = 1, bgcolor = color.new(c, 82)))
                array.push(lns, line.new(math.min(startI, time), p, endX, p, xloc = xloc.bar_time, color = c, width = 1, style = cat == "expected_move" ? line.style_dotted : (cat == "oi_by_expiry" or cat == "volume_by_expiry" or cat == "oi_mid" or cat == "volume_mid") ? line.style_dashed : line.style_solid))
                if showBlocks
                    array.push(lbs, label.new(endX, p, array.get(lvName, i) + " " + str.tostring(p, "#.##"), xloc = xloc.bar_time, style = label.style_label_left, color = color.new(c, 30), textcolor = color.white, size = size.small))
'''


def _s(text) -> str:
    """Strip characters that would break a Pine string or comment line."""
    return re.sub(r"\s+", " ", re.sub(r'["\\]', "", str(text))).strip()


def build_pine(levels: list, source: str, units: str, start_et=None) -> str:
    """levels: dicts with label, category, price. start_et: aware datetime when the levels were made (None = unknown)."""
    lv = sorted((x for x in levels if x.get("price") is not None), key=lambda x: -x["price"])
    prices = ", ".join(f"{x['price']:.2f}" for x in lv) or ""
    starts = ", ".join(str(int(x["start"].timestamp() * 1000)) if x.get("start") else "0" for x in lv) or "0"
    lows = ", ".join(f"{x['low']:.2f}" if x.get("low") is not None else "0.0" for x in lv) or "0.0"
    highs = ", ".join(f"{x['high']:.2f}" if x.get("high") is not None else "0.0" for x in lv) or "0.0"
    names = ", ".join(f'"{_s(x["label"])}"' for x in lv)
    cats = ", ".join(f'"{_s(x["category"])}"' for x in lv)
    if not lv:     # array.from() needs at least one element, so use a harmless placeholder that is never drawn
        prices, names, cats, starts, lows, highs = "0.0", '"none"', '"none"', "0", "0.0", "0.0"
    start = ("timestamp(\"America/New_York\", %d, %d, %d, %d, %d, 0)" % (start_et.year, start_et.month, start_et.day, start_et.hour, start_et.minute)) if start_et else "na"
    return (TEMPLATE.replace("__START__", start).replace("__SOURCE__", _s(source)).replace("__UNITS__", _s(units))
            .replace("__LOWS__", lows).replace("__HIGHS__", highs).replace("__STARTS__", starts).replace("__PRICES__", prices).replace("__NAMES__", names).replace("__CATS__", cats))
